{"file_path":"wordy.py","content":"_OPERATIONS = {
    "plus": lambda a, b: a + b,
    "minus": lambda a, b: a - b,
    "multiplied": lambda a, b: a * b,
    "divided": lambda a, b: _int_divide(a, b),
}


def _int_divide(a, b):
    quotient = a / b
    return int(quotient) if quotient >= 0 else -int(-quotient)


def _is_number(token):
    try:
        int(token)
        return True
    except ValueError:
        return False


def answer(question):
    if not question.startswith("What is") or not question.endswith("?"):
        raise ValueError("unknown operation")

    body = question[len("What is"):-1].strip()
    body = body.replace("multiplied by", "multiplied").replace("divided by", "divided")
    tokens = body.split()

    if not tokens:
        raise ValueError("syntax error")

    for token in tokens:
        if not _is_number(token) and token not in _OPERATIONS:
            raise ValueError("unknown operation")

    if not _is_number(tokens[0]):
        raise ValueError("syntax error")

    result = int(tokens[0])
    rest = tokens[1:]

    if len(rest) % 2 != 0:
        raise ValueError("syntax error")

    for i in range(0, len(rest), 2):
        op_token = rest[i]
        num_token = rest[i + 1]

        if op_token not in _OPERATIONS or not _is_number(num_token):
            raise ValueError("syntax error")

        result = _OPERATIONS[op_token](result, int(num_token))

    return result
"}

